#!/usr/bin/env bash



# set -e: exit on errors
# set -x: verbose logging

set -ex



# Configure bash globbing for recursive cp command

shopt -s globstar



# Set variables

PORT="_build/OoT Reloaded (Ship of Harkinian)"
EXT=".png"



# Remove and recreate work directories

rm -drf "$PORT"
rm -drf "_temp"

mkdir -p "$PORT"
mkdir -p "_temp"



# Copy textures to work directories

cp -r "Ports/Ship of Harkinian/"* "$PORT"

cp **"/Areas/"**"/THE LEGEND OF ZELDA"*"$EXT" "_temp"
#cp **"/Background/CI8/"**"/THE LEGEND OF ZELDA"*"$EXT" "_temp"
#cp **"/Background/JPEG/Single-File (Four-by-Three)/"**"/THE LEGEND OF ZELDA"*"$EXT" "_temp"
